(function () {
var SRC = "https://po-3.github.io/events.json";
var KEY = "tnr_evc_v2", TTL = 36e5, PAST_OPEN = 3;
var root = document.getElementById("tnr-evc");
if (!root) return;
if (document.body.classList.contains("page-index")) {
var box = document.getElementById("box2"), mod = root.closest(".hatena-module");
if (box && mod) {
var band = document.createElement("section");
band.className = "tnr-evc-band";
band.innerHTML = '<h2 class="tnr-band-h">イベントカレンダー。<span>これまでも。これからも。</span></h2>';
mod.style.width = "auto"; 
band.appendChild(mod);
box.parentNode.insertBefore(band, box.nextSibling);
}
}
function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]; }); }
function list(label, cls, items) {
if (!items || !items.length) return "";
return '<div class="tnr-evc-kv ' + cls + '"><span class="tnr-evc-k">' + label + "</span><span>" + items.map(esc).join("、") + "</span></div>";
}
var isWide = function () { return root.clientWidth >= 600; }, lastWide;
window.addEventListener("resize", function () { var w = isWide(); if (w === lastWide) return; lastWide = w; var f = root.querySelector(".tnr-evc-fold"); if (f) f.open = w; });
var DAY = 864e5, STALE = 14 * DAY;
var JST = function (d) { return new Date(d.getTime() + 9 * 36e5); };
function phase(e, now) {
if (e.status === "done") return "done";
if (e.status === "expected") return now - new Date(e.sort + "T00:00:00+09:00") > STALE ? "stale" : "plan";
var at = new Date(e.at), end = new Date(e.end || at.getTime() + 2 * 36e5);
if (now >= end) return "done";
if (now >= at) return "live";
return JST(now).toISOString().slice(0, 10) === JST(at).toISOString().slice(0, 10) ? "today" : "soon";
}
function badge(e, now) {
var p = phase(e, now);
if (p === "done") return '<span class="tnr-evc-badge is-done">済</span>';
if (p === "plan") return '<span class="tnr-evc-badge is-plan">予定</span>';
if (p === "stale") return '<span class="tnr-evc-badge is-plan">時期未定</span>';
if (p === "live") return '<span class="tnr-evc-badge is-live">開催中</span>';
if (p === "today") return '<span class="tnr-evc-badge is-count">今日</span>';
return '<span class="tnr-evc-badge is-count">あと' + Math.ceil((new Date(e.at) - now) / DAY) + "日</span>";
}
function big(w, b) { var i = w.indexOf("（"); return i > 0 ? esc(w.slice(0, i)) + b + '<span class="tnr-evc-big-sub">' + esc(w.slice(i)) + "</span>" : esc(w) + b; }
function when(e, now) { var y = JST(now).getUTCFullYear() + "年"; return e.when.indexOf(y) === 0 && e.when.length > y.length + 1 ? e.when.slice(y.length) : e.when; }
function link(e) { return '<a href="' + esc(e.src) + '" target="_blank" rel="noopener">' + esc(e.title) + "</a>"; }
function row(e, now) {
var items = (e.confirmed && e.confirmed.length ? e.confirmed : e.expected || []).map(esc).join("、");
return '<li class="tnr-evc-item"><div class="tnr-evc-when">' + esc(when(e, now)) + badge(e, now) + "</div>" +
'<div class="tnr-evc-name">' + link(e) + '<span class="tnr-evc-kind">' + esc(e.kind) + "</span></div>" +
(items ? '<div class="tnr-evc-items">' + items + "</div>" : "") + "</li>";
}
function render(data) {
var q = location.search.match(/evc-now=([^&]+)/), now = q ? new Date(decodeURIComponent(q[1])) : new Date();
var wide = lastWide = isWide(), next = [], past = [];
data.events.forEach(function (e) { (phase(e, now) === "done" ? past : next).push(e); });
var key = function (e) { return e.at || e.sort; };
next.sort(function (a, b) { return key(a) < key(b) ? -1 : 1; });
past.sort(function (a, b) { return key(a) > key(b) ? -1 : 1; });
var top = next[0], h = '<div class="tnr-evc-tile is-next"><div class="tnr-evc-label">これから</div>';
if (top) {
var p = phase(top, now);
var both = top.confirmed && top.confirmed.length && top.expected && top.expected.length;
h += '<div class="tnr-evc-hero"><div class="tnr-evc-big" style="display:flex;align-items:center;flex-wrap:wrap;gap:6px 12px">' +
big(when(top, now), badge(top, now)) + "</div>" +
'<div class="tnr-evc-hname">' + link(top) + '<span class="tnr-evc-kind">' + esc(top.kind) + "</span></div>" +
(both ? list("確定", "is-fixed", top.confirmed) + list("予定", "is-plan", top.expected)
: '<div class="tnr-evc-kv">' + (top.confirmed && top.confirmed.length ? top.confirmed : top.expected || []).map(esc).join("、") + "</div>") +
(p === "stale" ? '<div class="tnr-evc-note">' + esc(top.when) + "の見込みでしたが、Appleの告知はまだありません</div>" : top.note ? '<div class="tnr-evc-note">' + esc(top.note) + "</div>" : "") + "</div>";
if (next.length > 1) h += '<ol class="tnr-evc-list is-rest">' + next.slice(1).map(function (e) { return row(e, now); }).join("") + "</ol>";
} else h += '<div class="tnr-evc-note">告知も見込みも、まだありません。わかり次第ここに載せます</div>';
h += "</div>";
var pin = '<ol class="tnr-evc-list">' + past.slice(0, PAST_OPEN).map(function (e) { return row(e, now); }).join("") + "</ol>";
var years = [], byYear = {};
past.slice(PAST_OPEN).forEach(function (e) { var y = e.sort.slice(0, 4); if (!byYear[y]) { byYear[y] = []; years.push(y); } byYear[y].push(e); });
years.forEach(function (y) {
pin += '<details class="tnr-evc-more"><summary>' + y + "年（" + byYear[y].length + '件）を表示する</summary><ol class="tnr-evc-list">' +
byYear[y].map(function (e) { return row(e, now); }).join("") + "</ol></details>";
});
h += '<details class="tnr-evc-tile tnr-evc-fold is-past"' + (wide ? " open" : "") + '><summary class="tnr-evc-label">これまで<span class="tnr-evc-n">' + past.length + "件</span></summary>" + pin + "</details>";
root.querySelector(".tnr-evc-body").innerHTML = h;
root.querySelector(".tnr-evc-updated").textContent = data.updated;
}
var c = null;
try { c = JSON.parse(localStorage.getItem(KEY)); } catch (e) {}
if (c && c.d) render(c.d);
if (c && Date.now() - c.t < TTL) return;
fetch(SRC + "?v=" + Math.floor(Date.now() / TTL)).then(function (r) { return r.json(); }).then(function (d) {
render(d);
try { localStorage.setItem(KEY, JSON.stringify({ t: Date.now(), d: d })); } catch (e) {}
}).catch(function () {
if (!(c && c.d)) root.querySelector(".tnr-evc-body").innerHTML = '<div class="tnr-evc-tile is-hero"><div class="tnr-evc-note">読み込めませんでした。時間をおいて開き直してください</div></div>';
});
})();
